const el=(tag,text,cls)=>{const node=document.createElement(tag);if(text)node.textContent=text;if(cls)node.className=cls;return node;};
const names={basis:'Fakturagrundlag',confirmation:'Ordrebekræftelse',shipment:'Forsendelse og tracking',refund:'Refunderingsgrundlag',receipt:'Betalingskvittering',invoice:'Bogført faktura',proof:'Korrektur'};
const reasons={shipment:'Afventer registreret afsendelse.',receipt:'Afventer bekræftet hævning. Reservation er ikke betaling.',invoice:'Ingen bogført faktura registreret.',proof:'Send ny korrektur fra fanen Korrektur.'};
export function createDocumentRows(order,checkout){
 const root=el('div',null,'document-action-list'),entries=new Map(),customer=checkout?.shipping?.email||order.shipping?.email||'',billing=checkout?.billing?.email||customer;
 root.setAttribute('role','list');
 function ensure(type){if(entries.has(type))return entries.get(type);const row=el('div',null,'document-action-row'),info=el('div'),recipient=el('div',null,'document-recipient'),state=el('div',null,'document-readiness'),actions=el('div',null,'document-row-actions');row.setAttribute('role','listitem');info.append(el('strong',names[type]||type));if(type==='basis')info.append(el('small','Til manuel faktura i e-conomic'));
 const audience=el('strong',type==='basis'?'Financial · internt':'Kunden'),email=el('span',type==='basis'?'Indlæser modtager…':(type==='invoice'||type==='receipt'?billing:customer)||'E-mail mangler');recipient.append(audience,email);row.append(info,recipient,state,actions);root.append(row);const entry={row,info,recipient,email,state,actions,statuses:new Map(),setSent(key,message){if(message?.status==='sent')this.deliveries.set(key,message);else this.deliveries.delete(key);this.setStatus('delivery','');},deliveries:new Map(),setStatus(key,text){this.statuses.set(key,text);this.state.replaceChildren();const sent=[...this.deliveries.values()].sort((a,b)=>String(b.sentAt||b.lastSentAt||b.createdAt||'').localeCompare(String(a.sentAt||a.lastSentAt||a.createdAt||'')))[0];this.row.className='document-action-row'+(sent?' document-is-sent':'');if(sent){const at=sent.sentAt||sent.lastSentAt||sent.createdAt;this.state.append(el('p','Sendt · accepteret af mailserver','document-sent-badge'));this.state.append(el('p',[sent.to,at?new Date(at).toLocaleString('da-DK',{timeZone:'Europe/Copenhagen'}):''].filter(Boolean).join(' · '),'document-sent-detail'));}const seen=new Set();for(const [kind,value] of this.statuses)if(value&&!(sent&&kind==='mail')&&!seen.has(value)){seen.add(value);this.state.append(el('p',value,'document-status-'+kind));}}};entries.set(type,entry);return entry;}
 for(const type of ['basis','confirmation','shipment','receipt'])ensure(type);
 const context=order.attention||{};
 for(const mail of context.finance?.mail||[]){const type={accountant_basis:'basis',payment_receipt:'receipt',refund_basis:'refund'}[mail.kind];if(type)ensure(type).setSent(mail.key,mail);}
 if(context.confirmation)ensure('confirmation').setSent('automatic',context.confirmation);
 for(const mail of context.shipments||[])ensure('shipment').setSent(mail.id||mail.key,mail);
 for(const mail of context.proofs||[])if(mail.kind==='invitation'&&Number(mail.version)===Number(order.proof?.version))ensure('proof').setSent(mail.key,mail);
 for(const mail of context.correspondence||[])if(['confirmation','tracking','invoice'].includes(mail.action))ensure(mail.action==='tracking'?'shipment':mail.action).setSent(mail.id,mail);

 return {root,ensure,entries,customer,billing,shortReason:(type,reason)=>((type==='receipt'&&reason?.startsWith('Kvittering kræver registreret betaling'))||(type==='shipment'&&/^(Forsendelsesbekræftelse kræver registreret afsendelse|Afventer afsendelse)/.test(reason))||(type==='invoice'&&reason?.startsWith('Ingen bogført kundefaktura'))||(type==='proof'&&reason?.startsWith('Der er ingen aktiv korrektur hos kunden')))?reasons[type]:reason,reviewHost:el('div',null,'document-mail-review')};
}
export function attachResendRow(rows,option,button){const type=option.action==='tracking'?'shipment':option.action,row=rows.ensure(type);button.textContent={confirmation:'Gensend ordremail',invoice:'Gensend faktura',tracking:row.deliveries.size?'Gensend tracking':'Send tracking',proof:'Gensend kundelink'}[option.action]||option.label;button.title=option.reason||'Gennemse modtager og besked før afsendelse';row.setStatus('mail',option.available?'Klar til '+(option.action==='tracking'?'trackingmail.':'genafsendelse.'):(rows.shortReason(type,option.reason)||'Afventer oplysninger.'));row.actions.append(button);}
